-- One-time initial unit catalog only. No employee/manager/secretary grants.
-- Run only after 01_create_tables.sql, in STRATEGYKPI, on an EMPTY catalog.
WHENEVER SQLERROR EXIT SQL.SQLCODE
SET SERVEROUTPUT ON
DECLARE
  v_count NUMBER;
BEGIN
  IF USER <> 'STRATEGYKPI'
     OR SYS_CONTEXT('USERENV','CURRENT_SCHEMA') <> 'STRATEGYKPI' THEN
    RAISE_APPLICATION_ERROR(-20001, 'STOP: wrong schema');
  END IF;
  SELECT COUNT(*) INTO v_count FROM TARASOL_ORG_UNITS;
  IF v_count <> 0 THEN
    RAISE_APPLICATION_ERROR(-20003, 'STOP: catalog already contains rows');
  END IF;
END;
/

